export class AppComponent {
  constructor(http) {
    this.http = http;
    this.api = 'http://localhost:5000/api';
    this.token = localStorage.getItem('attendify_token') || '';
    this.user = JSON.parse(localStorage.getItem('attendify_user') || 'null');
