    this.busy = false;
    this.message = '';
    this.error = '';
    this.todayAttendance = null;
    this.attendance = [];
    this.leaves = [];
    this.balance = {};
    this.employees = [];
    this.adminAttendance = [];
    this.adminLeaves = [];
    this.summary = {
      total: 0,
      present: 0,
      absent: 0,
      late: 0,
      onLeave: 0
    };
    this.loginForm = {
      email: 'employee@attendify.local',
      password: 'Employee@12345'
    };
    this.leaveForm = {
      type: 'annual',
      startDate: '',
      endDate: '',
      reason: ''
    };
    this.employeeForm = {
      name: '',
      email: '',
      password: 'Welcome@123',
      employeeId: '',
      department: '',
      designation: '',
      phone: '',
      annual: 24,
      sick: 8,
      casual: 10
    };
    this.selectedPhoto = null;
    this.selectedPreview = '';
    this.latitude = null;
    this.longitude = null;
    this.accuracy = null;
    this.currentDate = new Date();
    if (this.token && this.user) this.loadData();
  }
  get isAdmin() {
    return this.user?.role === 'admin';
  }
  get headers() {
    return {
      headers: new HttpHeaders({
        Authorization: `Bearer ${this.token}`
      })
    };
  }
  notify(text, isError = false) {
    this.message = isError ? '' : text;
    this.error = isError ? text : '';
    setTimeout(() => {
      this.message = '';
      this.error = '';
    }, 4500);
  }
  login() {
    this.busy = true;
    this.http.post(`${this.api}/auth/login`, this.loginForm).subscribe({
      next: r => {
        this.token = r.token;
        this.user = r.user;
        localStorage.setItem('attendify_token', this.token);
        localStorage.setItem('attendify_user', JSON.stringify(this.user));
        this.busy = false;
        this.loadData();
      },
      error: e => {
        this.busy = false;
        this.notify(e.error?.message || 'Unable to sign in.', true);
      }
    });
  }
  logout() {
    localStorage.removeItem('attendify_token');
    localStorage.removeItem('attendify_user');
