    this.http.get(`${this.api}/attendance/today`, this.headers).subscribe({
      next: r => this.todayAttendance = r || null
    });
    this.http.get(`${this.api}/attendance/mine`, this.headers).subscribe({
      next: r => this.attendance = r
    });
    this.http.get(`${this.api}/leaves/mine`, this.headers).subscribe({
      next: r => this.leaves = r
    });
    this.http.get(`${this.api}/leaves/balance`, this.headers).subscribe({
      next: r => this.balance = r
    });
  }
  loadAdmin() {
    this.http.get(`${this.api}/attendance/admin/summary`, this.headers).subscribe({
      next: r => this.summary = r
    });
    this.http.get(`${this.api}/employees`, this.headers).subscribe({
      next: r => this.employees = r
    });
    this.http.get(`${this.api}/attendance/admin/all`, this.headers).subscribe({
      next: r => this.adminAttendance = r
    });
    this.http.get(`${this.api}/leaves/admin/all`, this.headers).subscribe({
      next: r => this.adminLeaves = r
    });
  }
  changePage(page) {
    this.page = page;
    if (this.isAdmin) this.loadAdmin();else this.loadEmployee();
