import { Component } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';

@Component({ selector: 'app-root', templateUrl: './app.component.html' })
export class AppComponent {
  api = 'http://localhost:5000/api'; token = localStorage.getItem('attendify_token') || ''; user: any = JSON.parse(localStorage.getItem('attendify_user') || 'null');
  page = 'dashboard'; busy = false; message = ''; error = ''; todayAttendance: any = null; attendance: any[] = []; leaves: any[] = []; balance: any = {}; employees: any[] = []; adminAttendance: any[] = []; adminLeaves: any[] = []; summary: any = { total: 0, present: 0, absent: 0, late: 0, onLeave: 0 };
  loginForm: any = { email: 'employee@attendify.local', password: 'Employee@12345' };
  leaveForm: any = { type: 'annual', startDate: '', endDate: '', reason: '' }; employeeForm: any = { name: '', email: '', password: 'Welcome@123', employeeId: '', department: '', designation: '', phone: '', annual: 24, sick: 8, casual: 10 };
  selectedPhoto: File | null = null; selectedPreview = ''; latitude: number | null = null; longitude: number | null = null; accuracy: number | null = null; currentDate = new Date();
  constructor(private http: HttpClient) { if (this.token && this.user) this.loadData(); }
  get isAdmin() { return this.user?.role === 'admin'; }
  get headers() { return { headers: new HttpHeaders({ Authorization: `Bearer ${this.token}` }) }; }
  notify(text: string, isError = false) { this.message = isError ? '' : text; this.error = isError ? text : ''; setTimeout(() => { this.message = ''; this.error = ''; }, 4500); }
  login() { this.busy = true; this.http.post<any>(`${this.api}/auth/login`, this.loginForm).subscribe({ next: r => { this.token = r.token; this.user = r.user; localStorage.setItem('attendify_token', this.token); localStorage.setItem('attendify_user', JSON.stringify(this.user)); this.busy = false; this.loadData(); }, error: e => { this.busy = false; this.notify(e.error?.message || 'Unable to sign in.', true); } }); }
  logout() { localStorage.removeItem('attendify_token'); localStorage.removeItem('attendify_user'); this.token = ''; this.user = null; this.page = 'dashboard'; }
  loadData() { if (this.isAdmin) { this.loadAdmin(); } else { this.loadEmployee(); } }
  loadEmployee() { this.http.get<any>(`${this.api}/attendance/today`, this.headers).subscribe({ next: r => this.todayAttendance = r || null }); this.http.get<any[]>(`${this.api}/attendance/mine`, this.headers).subscribe({ next: r => this.attendance = r }); this.http.get<any[]>(`${this.api}/leaves/mine`, this.headers).subscribe({ next: r => this.leaves = r }); this.http.get<any>(`${this.api}/leaves/balance`, this.headers).subscribe({ next: r => this.balance = r }); }
  loadAdmin() { this.http.get<any>(`${this.api}/attendance/admin/summary`, this.headers).subscribe({ next: r => this.summary = r }); this.http.get<any[]>(`${this.api}/employees`, this.headers).subscribe({ next: r => this.employees = r }); this.http.get<any[]>(`${this.api}/attendance/admin/all`, this.headers).subscribe({ next: r => this.adminAttendance = r }); this.http.get<any[]>(`${this.api}/leaves/admin/all`, this.headers).subscribe({ next: r => this.adminLeaves = r }); }
  changePage(page: string) { this.page = page; if (this.isAdmin) this.loadAdmin(); else this.loadEmployee(); }
  onPhoto(event: any) { const file = event.target.files?.[0]; if (!file) return; if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type)) { this.notify('Please select JPG, PNG or WEBP image.', true); return; } if (file.size > 5 * 1024 * 1024) { this.notify('Photo must be smaller than 5 MB.', true); return; } this.selectedPhoto = file; this.selectedPreview = URL.createObjectURL(file); }
  getLocation() { return new Promise<void>((resolve, reject) => { if (!navigator.geolocation) { reject('Geolocation is not supported by this browser.'); return; } navigator.geolocation.getCurrentPosition(pos => { this.latitude = pos.coords.latitude; this.longitude = pos.coords.longitude; this.accuracy = pos.coords.accuracy; resolve(); }, () => reject('Location permission denied. Please allow location access.'), { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }); }); }
  async markAttendance(action: 'check-in' | 'check-out') { try { if (!this.selectedPhoto) { this.notify('Please take or upload your attendance photo first.', true); return; } this.busy = true; await this.getLocation(); const data = new FormData(); data.append('photo', this.selectedPhoto); data.append('latitude', String(this.latitude)); data.append('longitude', String(this.longitude)); data.append('accuracy', String(this.accuracy)); this.http.post<any>(`${this.api}/attendance/${action}`, data, this.headers).subscribe({ next: r => { this.busy = false; this.selectedPhoto = null; this.selectedPreview = ''; this.notify(action === 'check-in' ? 'Check-in marked successfully.' : 'Check-out marked successfully.'); this.loadEmployee(); }, error: e => { this.busy = false; this.notify(e.error?.message || 'Attendance could not be saved.', true); } }); } catch (e: any) { this.busy = false; this.notify(e, true); } }
  submitLeave() { if (!this.leaveForm.startDate || !this.leaveForm.endDate || !this.leaveForm.reason.trim()) { this.notify('Please complete all leave fields.', true); return; } this.http.post(`${this.api}/leaves`, this.leaveForm, this.headers).subscribe({ next: () => { this.notify('Leave request submitted.'); this.leaveForm = { type: 'annual', startDate: '', endDate: '', reason: '' }; this.loadEmployee(); }, error: e => this.notify(e.error?.message || 'Leave request failed.', true) }); }
  addEmployee() { const payload = { ...this.employeeForm, leaveAllowance: { annual: Number(this.employeeForm.annual), sick: Number(this.employeeForm.sick), casual: Number(this.employeeForm.casual) } }; this.http.post(`${this.api}/employees`, payload, this.headers).subscribe({ next: () => { this.notify('Employee created successfully.'); this.employeeForm = { name: '', email: '', password: 'Welcome@123', employeeId: '', department: '', designation: '', phone: '', annual: 24, sick: 8, casual: 10 }; this.loadAdmin(); }, error: e => this.notify(e.error?.message || 'Could not create employee.', true) }); }
  reviewLeave(id: string, status: string) { const remark = window.prompt(`Optional remark for ${status}:`) || ''; this.http.patch(`${this.api}/leaves/admin/${id}/review`, { status, adminRemark: remark }, this.headers).subscribe({ next: () => { this.notify(`Leave ${status}.`); this.loadAdmin(); }, error: e => this.notify(e.error?.message || 'Unable to update leave.', true) }); }
  deactivateEmployee(id: string) { if (!confirm('Deactivate this employee account?')) return; this.http.delete(`${this.api}/employees/${id}`, this.headers).subscribe({ next: () => { this.notify('Employee deactivated.'); this.loadAdmin(); }, error: e => this.notify(e.error?.message || 'Action failed.', true) }); }
  mapUrl(lat: number, lng: number) { return `https://www.google.com/maps?q=${lat},${lng}`; }
  viewPhoto(filename: string) { this.http.get(`${this.api}/attendance/photo/${encodeURIComponent(filename)}`, { headers: new HttpHeaders({ Authorization: `Bearer ${this.token}` }), responseType: 'blob' }).subscribe({ next: blob => { const url = URL.createObjectURL(blob); window.open(url, '_blank'); setTimeout(() => URL.revokeObjectURL(url), 60000); }, error: () => this.notify('Photo could not be opened.', true) }); }
  exportCsv(filename: string, rows: any[], columns: string[]) { if (!rows.length) { this.notify('There is no data to export.', true); return; } const escape = (value: any) => `\"${String(value ?? '').replace(/\"/g, '\"\"')}\"`; const csv = [columns.join(','), ...rows.map(row => columns.map(key => escape(key.split('.').reduce((v: any, k: string) => v?.[k], row))).join(','))].join('\n'); const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = filename; a.click(); URL.revokeObjectURL(url); }
  hours(row: any) { if (!row.checkOut) return 'In progress'; const ms = new Date(row.checkOut).getTime() - new Date(row.checkIn).getTime(); return `${Math.floor(ms / 3600000)}h ${Math.floor((ms % 3600000) / 60000)}m`; }
  get pendingLeaves() { return this.adminLeaves.filter(l => l.status === 'pending').length; }
  get pendingEmployeeLeaves() { return this.leaves.filter(l => l.status === 'pending').length; }
  get attendanceThisMonth() { const month = new Date().toISOString().slice(0, 7); return this.attendance.filter(row => String(row.dateKey || '').startsWith(month)).length; }
}
